# =============================================================================
# GENERATE SUMMARY TABLES BY TAXONOMIC LEVEL (Excel with one sheet per level)
# Andrea Moriñigo — Bioinformatics MSc Thesis
# =============================================================================
#
# Sheet names, titles, column headers and labels are in English.
#
# This script reads the table already generated by wilcoxon_comparison.R
# (tabla1_wilcoxon_completo.csv, which combines the 5 taxonomic levels in a
# single file) and builds one Excel sheet per taxonomic level (Class, Order,
# Family, Genus, Species), with:
#
#   1) SUMMARY: n and % of "Both methods" / "Morphology only" / "eDNA only"
#      taxa, and how many of each group are significant according to Bonferroni.
#
#   2) DETAIL: full list of taxa at that level, with their median, mean and
#      p-value, sorted as follows:
#         - first the "Both methods" group, then "Morphology only", then "eDNA only"
#         - within each group, significant (Bonferroni) taxa first, then the rest
#         - within each of those blocks, from highest to lowest abundance
#      "Both methods" taxa also carry a direction column (overestimated /
#      underestimated / conflicting mean vs median), where over/under combine
#      mean and median and "conflicting" = mean and median disagree in direction.
#
# In addition, for Order/Family/Genus/Species (not Class) a SEPARATE SHEET
# ("<Level>_MIDORI") is generated with MIDORI database coverage (see Block 6bis).
# It goes on its own sheet, not as a third table below the detail table,
# because Excel only allows one frozen row per sheet — this way each sheet
# keeps its own correct frozen header when scrolling.
#
# NOTE on which "abundance" is used for sorting: "Both methods" taxa have
# abundance in both methods at once, so they are sorted by the mean of
# (mean_morpho, mean_cox1). "Morphology only" taxa are sorted by their
# mean_morpho, and "eDNA only" by their mean_cox1. That figure is computed only
# internally for sorting and is NO longer shown in the Excel (column removed on request).
#
# If you don't have the openxlsx package installed, run first: install.packages("openxlsx")

library(dplyr)
library(openxlsx)

# =============================================================================
# BLOCK 1 — PATHS (adjust if your folder structure differs)
# =============================================================================
# Lee directamente la salida de wilcoxon_comparison.R (no una copia manual en final_data/,
# que se quedaba vieja). Así el resumen siempre refleja el último análisis.
path_in  <- "C:/Users/andre/Desktop/TFM_AZTI/comparison/archivos/download_from_r/wilcoxon_denominador_CLASS.csv"
path_out <- "C:/Users/andre/Desktop/TFM_AZTI/comparison/archivos/download_from_r/Taxonomic_summary_by_level_EN.xlsx"

# =============================================================================
# BLOCK 2 — LOAD DATA
# =============================================================================
# read.csv2 assumes ";" separator and comma as decimal mark, which is how the
# csv is stored. Unquoted "NA" values in the csv are automatically read as R's NA.
data <- read.csv2(path_in, stringsAsFactors = FALSE, fileEncoding = "UTF-8")

# Levels as they appear in the "level" column, and the name each Excel sheet
# will get (in English, same order)
levels_vec  <- c("Class", "Order", "Family", "Genus", "Species")
sheet_names <- c("Class", "Order", "Family", "Genus", "Species")

# =============================================================================
# BLOCK 3 — LABEL TRANSLATIONS
# =============================================================================
translate_group <- function(x) {
  case_when(
    x == "both"             ~ "Both methods",
    x == "only_morphology"  ~ "Morphology only",
    x == "only_eDNA"        ~ "eDNA only",
    TRUE ~ x
  )
}

# =============================================================================
# BLOCK 4 — FUNCTION: build the summary table for a level
# =============================================================================
build_summary <- function(level_data) {

  # Direction classification (same mean+median logic as the detail table), to count
  # how many SIGNIFICANT taxa are overestimated / underestimated / conflicting at
  # this level. Only applies to the "both" group.
  level_data <- level_data %>%
    mutate(
      # CORRECCION: no se recalcula la direccion aqui. Se reutiliza la columna
      # `direction` que ya calcula wilcoxon_comparison.R (unica fuente de verdad). Antes
      # se rehacia con sign(median_cox1 - median_morpho), lo que podia no coincidir
      # con la clasificacion del detalle y contaba como "conflict" cualquier caso
      # que no encajase en las ramas anteriores (rama TRUE ~ "conflict").
      clasif_dir = case_when(
        present_in != "both"                  ~ NA_character_,
        direction == "overestimated_in_eDNA"  ~ "over",
        direction == "underestimated_in_eDNA" ~ "under",
        direction == "conflict"               ~ "conflict",
        TRUE                                  ~ "nodiff"
      )
    )

  summary_tbl <- level_data %>%
    group_by(present_in) %>%
    summarise(
      n                     = n(),
      n_significant_bonf    = sum(significant_bonferroni == "YES"),
      n_not_significant_bonf = sum(significant_bonferroni == "NO"),
      n_overestimated       = sum(clasif_dir == "over"     & significant_bonferroni == "YES", na.rm = TRUE),
      n_underestimated      = sum(clasif_dir == "under"    & significant_bonferroni == "YES", na.rm = TRUE),
      n_conflicting         = sum(clasif_dir == "conflict" & significant_bonferroni == "YES", na.rm = TRUE),
      n_conflicting_ns      = sum(clasif_dir == "conflict" & significant_bonferroni == "NO",  na.rm = TRUE),
      .groups = "drop"
    ) %>%
    mutate(
      percentage            = round(100 * n / sum(n), 1),
      group                 = translate_group(present_in)
    ) %>%
    select(group, n, percentage, n_significant_bonf,
           n_not_significant_bonf,
           n_overestimated, n_underestimated, n_conflicting, n_conflicting_ns)

  # Force fixed order of the 3 groups, filling with 0 if one were missing
  group_order <- c("Both methods", "Morphology only", "eDNA only")
  summary_tbl <- summary_tbl[match(group_order, summary_tbl$group), ]
  summary_tbl$group <- group_order
  summary_tbl[is.na(summary_tbl)] <- 0

  # Total row
  total <- data.frame(
    group                   = "TOTAL",
    n                       = sum(summary_tbl$n),
    percentage              = 100,
    n_significant_bonf      = sum(summary_tbl$n_significant_bonf),
    n_not_significant_bonf  = sum(summary_tbl$n_not_significant_bonf),
    n_overestimated         = sum(summary_tbl$n_overestimated),
    n_underestimated        = sum(summary_tbl$n_underestimated),
    n_conflicting           = sum(summary_tbl$n_conflicting),
    n_conflicting_ns        = sum(summary_tbl$n_conflicting_ns)
  )
  summary_tbl <- rbind(summary_tbl, total)

  colnames(summary_tbl) <- c("Group", "n", "% of total",
                              "n significant (Bonferroni)",
                              "n not significant (Bonferroni)",
                              "n overestimated in eDNA (sig.)",
                              "n underestimated in eDNA (sig.)",
                              "n conflicting mean-median (sig.)",
                              "n conflicting mean-median (not sig.)")
  return(summary_tbl)
}

# =============================================================================
# BLOCK 5 — FUNCTION: build the detail table for a level
# =============================================================================
build_detail <- function(level_data) {

  detail <- level_data %>%
    mutate(
      reference_abundance = case_when(
        present_in == "both"            ~ (mean_morpho + mean_cox1) / 2,
        present_in == "only_morphology" ~ mean_morpho,
        present_in == "only_eDNA"       ~ mean_cox1
      ),
      significant_bonf = ifelse(significant_bonferroni == "YES", "Yes", "No"),
      # Direction combining MEDIAN and MEAN (same logic as wilcoxon_comparison.R):
      #   - if median and mean agree on direction -> that direction (over/under)
      #   - if the median ties (e.g. 0 in both methods) the mean decides -> over/under
      #     (several over/underestimated taxa have median = 0; noted in the text)
      #   - if the mean ties, the median decides
      #   - if median and mean point in OPPOSITE directions -> "Conflicting (mean vs median)"
      #     (median ties at 0 are excluded: they go as over/under)
      dir_med_sign  = sign(median_cox1 - median_morpho),   #  1 over · -1 under · 0 tie
      dir_mean_sign = sign(mean_cox1   - mean_morpho),
      direction = case_when(
        present_in != "both"                               ~ NA_character_,
        dir_med_sign == dir_mean_sign & dir_med_sign ==  1 ~ "Overestimated in eDNA",
        dir_med_sign == dir_mean_sign & dir_med_sign == -1 ~ "Underestimated in eDNA",
        dir_med_sign == dir_mean_sign & dir_med_sign ==  0 ~ "Not concordant",
        dir_med_sign  == 0 & dir_mean_sign ==  1           ~ "Overestimated in eDNA",
        dir_med_sign  == 0 & dir_mean_sign == -1           ~ "Underestimated in eDNA",
        dir_mean_sign == 0 & dir_med_sign  ==  1           ~ "Overestimated in eDNA",
        dir_mean_sign == 0 & dir_med_sign  == -1           ~ "Underestimated in eDNA",
        TRUE                                               ~ "Conflicting (mean vs median)"
      ),
      group       = translate_group(present_in),
      group_order = case_when(                        # 1=Both, 2=Morpho only, 3=eDNA only
        present_in == "both"            ~ 1,
        present_in == "only_morphology" ~ 2,
        present_in == "only_eDNA"       ~ 3
      ),
      sig_order = ifelse(significant_bonferroni == "YES", 0, 1)   # significant first
    ) %>%
    arrange(group_order, sig_order, desc(reference_abundance)) %>%
    select(
      taxon, group, significant_bonf, direction,
      median_morpho = median_morpho, median_eDNA = median_cox1,
      mean_morpho   = mean_morpho,   mean_eDNA   = mean_cox1,
      p_value = p_value, p_value_bonferroni = p_adjust_bonferroni
    )

  colnames(detail) <- c("Taxon", "Group", "Significant (Bonferroni)",
                         "Direction (only 'Both methods')",
                         "Median morphology", "Median eDNA",
                         "Mean morphology", "Mean eDNA",
                         "p-value", "Adjusted p-value (Bonferroni)")
  return(detail)
}

# =============================================================================
# BLOCK 6bis — MIDORI COVERAGE (Order / Family / Genus / Species)
# =============================================================================
# This block generates, for Order, Family, Genus and Species (not Class,
# because Class was never checked against MIDORI), a "<Level>_MIDORI" sheet
# with two tables:
#   a) "Finest level with reference": ALWAYS the same table on the 4 sheets,
#      because it describes the coverage of the original 78 species (it does
#      not change depending on the level of the sheet it's shown on)
#   b) the list of ALL taxa at THAT specific level (present and absent in
#      MIDORI at their own level), with their full taxonomic path
#
# IMPORTANT — scope: this MIDORI check was only done for the 78 "Morphology
# only" species that were exported to midori_comparison_completo.py
# (sp_morpho_compare.csv file), NOT for the 634/399/157/25 "Morphology only"
# species/genera/families/orders that appear in table 2. In other words: this
# MIDORI table is a smaller, more specific subset, consistent with the section
# of your thesis that already says "78 species". The genera/families/orders in
# this table come from deduplicating those 78 species by genus/family/order.
#
# The compare_MIDORI_con_order.csv file is generated by midori_comparison.py: it is a
# plain CSV (real header on the 1st line, ";" separator, UTF-8 encoding), with no
# decorative rows. Read it directly, without skip.

midori_path <- "C:/Users/andre/Desktop/TFM_AZTI/comparison/archivos/download_from_python/compare_MIDORI_con_order.csv"

midori <- read.csv2(midori_path, stringsAsFactors = FALSE, fileEncoding = "UTF-8")

to_logical <- function(x) toupper(trimws(as.character(x))) == "TRUE"
midori$en_MIDORI_especie <- to_logical(midori$en_MIDORI_especie)
midori$en_MIDORI_genero  <- to_logical(midori$en_MIDORI_genero)
midori$family_en_MIDORI  <- to_logical(midori$family_en_MIDORI)
midori$order_en_MIDORI   <- to_logical(midori$order_en_MIDORI)

# One row per unique taxon at each level (deduplicated from the 78 species).
# All 4 boolean columns are kept (not just the one for its own level) because
# they're needed for the "cascade": if a taxon has no reference at its own
# level, check whether it has one at a higher rank (genus > family > order).
midori_order   <- midori[!is.na(midori$Order) & !duplicated(midori$Order),
                          c("Class", "Order", "order_en_MIDORI")]
midori_family  <- midori[!duplicated(midori$Family),
                          c("Class", "Order", "Family", "family_en_MIDORI", "order_en_MIDORI")]
midori_genus   <- midori[!duplicated(midori$Genus),
                          c("Class", "Order", "Family", "Genus",
                            "en_MIDORI_genero", "family_en_MIDORI", "order_en_MIDORI")]
midori_species <- midori[!duplicated(midori$Specie),
                          c("Class", "Order", "Family", "Genus", "Specie",
                            "en_MIDORI_especie", "en_MIDORI_genero", "family_en_MIDORI", "order_en_MIDORI")]

# Which table / presence column / path columns to use for each level
midori_level_tables <- list(
  Order   = list(data = midori_order,   presence_col = "order_en_MIDORI",
                  path_cols = c("Class"),                       taxon_col = "Order"),
  Family  = list(data = midori_family,  presence_col = "family_en_MIDORI",
                  path_cols = c("Class", "Order"),               taxon_col = "Family"),
  Genus   = list(data = midori_genus,   presence_col = "en_MIDORI_genero",
                  path_cols = c("Class", "Order", "Family"),     taxon_col = "Genus"),
  Species = list(data = midori_species, presence_col = "en_MIDORI_especie",
                  path_cols = c("Class", "Order", "Family", "Genus"), taxon_col = "Specie")
)

# -----------------------------------------------------------------------------
# Function: "finest level with reference in MIDORI" table, computed ONCE over
# the 78 species (not per taxonomic level). For each of the 78 "Morphology
# only" species, checks whether it has a species-level reference; if not,
# whether its genus has one; if not, its family; if not, its order; and if
# none of that, "None". This is the same table (36 species / 31 genus / 8
# family / 2 order / 1 none) that goes IDENTICALLY on the 4 _MIDORI sheets,
# because it describes the coverage of the original 78 species, not something
# different per level.
# -----------------------------------------------------------------------------
build_species_cascade_table <- function(midori) {
  cascade <- c("en_MIDORI_especie", "en_MIDORI_genero", "family_en_MIDORI", "order_en_MIDORI")
  labels  <- c(en_MIDORI_especie = "Species", en_MIDORI_genero = "Genus",
               family_en_MIDORI = "Family", order_en_MIDORI = "Order")

  values <- midori[, cascade, drop = FALSE]
  classification <- apply(values, 1, function(row) {
    idx <- which(row)[1]           # first column (finest to coarsest) that is TRUE
    if (is.na(idx)) "None" else labels[[cascade[idx]]]
  })

  category_levels <- c(unname(labels[cascade]), "None")
  counts <- table(factor(classification, levels = category_levels))

  summary_tbl <- data.frame(
    `Finest level with reference` = names(counts),
    `No. of species` = as.integer(counts),
    `% of total` = round(100 * as.integer(counts) / sum(counts), 1),
    check.names = FALSE
  )

  total <- data.frame(
    `Finest level with reference` = "Total", `No. of species` = sum(summary_tbl$`No. of species`), `% of total` = 100,
    check.names = FALSE
  )
  rbind(summary_tbl, total)
}

# -----------------------------------------------------------------------------
# Function: list of ALL taxa (present and absent) in MIDORI, with their
# taxonomic path and a status column. Order: present taxa first, then absent
# ones; alphabetical by taxon name within each block.
# -----------------------------------------------------------------------------
build_all_midori_list <- function(level_data, presence_col, path_cols, taxon_col) {
  tbl <- level_data[, c(path_cols, taxon_col, presence_col)]

  tbl$Status <- ifelse(tbl[[presence_col]], "Present in MIDORI", "Absent in MIDORI")
  tbl$status_order <- ifelse(tbl[[presence_col]], 0, 1)   # present first
  tbl <- tbl[order(tbl$status_order, tbl[[taxon_col]]), ]

  # Full path as text, in addition to the separate columns
  tbl$Full_path <- apply(tbl[, c(path_cols, taxon_col)], 1,
                          function(x) paste(na.omit(x), collapse = " > "))

  tbl[[presence_col]] <- NULL
  tbl$status_order <- NULL

  column_translation <- c(Class = "Class", Order = "Order", Family = "Family",
                           Genus = "Genus", Specie = "Species")
  colnames(tbl)[colnames(tbl) %in% names(column_translation)] <-
    column_translation[colnames(tbl)[colnames(tbl) %in% names(column_translation)]]
  colnames(tbl)[colnames(tbl) == "Full_path"] <- "Full path"

  rownames(tbl) <- NULL
  return(tbl)
}

# =============================================================================
# BLOCK 6 — BUILD THE EXCEL FILE, ONE SHEET PER LEVEL
# =============================================================================
wb <- createWorkbook()

style_title  <- createStyle(textDecoration = "bold", fontSize = 13)
style_header <- createStyle(textDecoration = "bold", fgFill = "#D9E1F2",
                             border = "Bottom", halign = "center")

# Styles for the cascade table: same light blue as the rest of the Excel
# (style_header), not the teal from the example photo. Total row bold with
# light background, source note in italics.
style_header_cascade <- createStyle(textDecoration = "bold", fgFill = "#D9E1F2",
                                     border = "Bottom", halign = "center")
style_total_cascade  <- createStyle(textDecoration = "bold", fgFill = "#DCE6F1",
                                     border = "Top", borderStyle = "thin")
style_source <- createStyle(textDecoration = "italic", fontColour = "#666666", fontSize = 9)

# Cascade table: computed ONCE (does not depend on the level) and repeated
# identically on the 4 _MIDORI sheets
species_cascade_table <- build_species_cascade_table(midori)

for (i in seq_along(levels_vec)) {

  current_level <- levels_vec[i]
  sheet         <- sheet_names[i]

  level_data <- data %>% filter(level == current_level)

  summary_table <- build_summary(level_data)
  detail_table  <- build_detail(level_data)

  addWorksheet(wb, sheet)

  # --- Summary block ---
  writeData(wb, sheet, paste0("Summary — ", sheet), startRow = 1, startCol = 1)
  addStyle(wb, sheet, style_title, rows = 1, cols = 1)
  writeData(wb, sheet, summary_table, startRow = 3, startCol = 1, headerStyle = style_header)

  # --- Detail block (starts a few rows after the summary) ---
  detail_title_row <- 3 + nrow(summary_table) + 3
  writeData(wb, sheet, paste0("Taxon detail — ", sheet), startRow = detail_title_row, startCol = 1)
  addStyle(wb, sheet, style_title, rows = detail_title_row, cols = 1)

  detail_header_row <- detail_title_row + 2
  writeData(wb, sheet, detail_table, startRow = detail_header_row, startCol = 1, headerStyle = style_header)

  # Frozen row at the detail table header. Since this sheet no longer carries
  # the MIDORI table below it (it goes on its own sheet, see below), this
  # frozen row is valid for the whole scroll of the sheet.
  freezePane(wb, sheet, firstActiveRow = detail_header_row + 1)
  setColWidths(wb, sheet, cols = 1:ncol(detail_table), widths = "auto")

  cat("Sheet generated:", sheet, "(", nrow(detail_table), "taxa )\n")

  # --- Separate sheet for MIDORI coverage (Order, Family, Genus, Species; not Class) ---
  if (current_level %in% names(midori_level_tables)) {

    midori_sheet <- paste0(sheet, "_MIDORI")
    info <- midori_level_tables[[current_level]]
    all_midori_table <- build_all_midori_list(info$data, info$presence_col,
                                               info$path_cols, info$taxon_col)

    addWorksheet(wb, midori_sheet)

    # --- Table 1: "Finest level with reference" — SAME on the 4 MIDORI sheets ---
    writeData(wb, midori_sheet, "Finest level with reference in MIDORI (78 'Morphology only' species checked)",
              startRow = 1, startCol = 1)
    addStyle(wb, midori_sheet, style_title, rows = 1, cols = 1)

    cascade_row <- 2   # no blank row between the title and the table
    writeData(wb, midori_sheet, species_cascade_table, startRow = cascade_row, startCol = 1, headerStyle = style_header_cascade)
    addStyle(wb, midori_sheet, style_total_cascade, rows = cascade_row + nrow(species_cascade_table), cols = 1:3)

    # (nota de fuente eliminada a petición)

    # --- Table 2: full list of taxa for THIS level (present and absent), with path ---
    all_taxa_title_row <- cascade_row + nrow(species_cascade_table) + 3
    writeData(wb, midori_sheet, paste0(sheet, " taxa (present and absent in MIDORI)"),
              startRow = all_taxa_title_row, startCol = 1)
    addStyle(wb, midori_sheet, style_title, rows = all_taxa_title_row, cols = 1)

    all_taxa_header_row <- all_taxa_title_row + 1   # no blank row between the title and the table
    writeData(wb, midori_sheet, all_midori_table, startRow = all_taxa_header_row, startCol = 1, headerStyle = style_header)

    # Frozen row at the taxon list header (the long table on this sheet)
    freezePane(wb, midori_sheet, firstActiveRow = all_taxa_header_row + 1)
    setColWidths(wb, midori_sheet, cols = 1:ncol(all_midori_table), widths = "auto")

    cat("Sheet generated:", midori_sheet, "(", nrow(all_midori_table), "taxa in total )\n")
  }
}

saveWorkbook(wb, path_out, overwrite = TRUE)
cat("\nExcel saved at:", path_out, "\n")


# =============================================================================
# GENERAR TABLAS RESUMEN POR NIVEL TAXONÓMICO (Excel con una pestaña por nivel)
# Andrea Moriñigo — TFM Bioinformática
# =============================================================================
#
# Este script lee la tabla que ya genera wilcoxon_comparison.R (tabla1_wilcoxon_completo.csv,
# que junta los 5 niveles taxonómicos en un único fichero) y construye una pestaña de
# Excel por nivel taxonómico (Clase, Orden, Familia, Género, Especie), con:
#
#   1) RESUMEN: nº y % de taxones "Ambos métodos" / "Solo morfología" / "Solo eDNA",
#      y cuántos de cada grupo son significativos según Bonferroni.
#
#   2) DETALLE: listado completo de taxones de ese nivel, con su mediana, media y
#      p-valor, ordenado así:
#         - primero el grupo "Ambos métodos", después "Solo morfología", después "Solo eDNA"
#         - dentro de cada grupo, primero los significativos por Bonferroni, después el resto
#         - dentro de cada uno de esos bloques, de mayor a menor abundancia
#      Los taxones "Ambos métodos" llevan además una columna con la dirección
#      (sobreestimado / subestimado / conflicto media-mediana), donde over/under
#      combinan media y mediana y "conflicto" = media y mediana discrepan.
#
# Además, para Orden/Familia/Género/Especie (no Clase) se genera una PESTAÑA APARTE
# ("<Nivel>_MIDORI") con la cobertura en la base de datos MIDORI (ver Bloque 6bis).
# Va en pestaña separada, y no como tercera tabla debajo del detalle, porque Excel
# solo admite una fila fija por pestaña — así cada pestaña conserva su propia
# cabecera fija correcta al hacer scroll.
#
# NOTA sobre qué "abundancia" se usa para ordenar: los taxones "Ambos métodos" tienen
# abundancia en los dos métodos a la vez, así que se ordenan por la media de
# (media_morfo, media_eDNA). Los "Solo morfología" se ordenan por su media_morfo, y los
# "Solo eDNA" por su media_eDNA. Esa cifra se calcula solo por dentro para ordenar y ya
# NO se muestra en el Excel (se quitó la columna a petición).
#
# Si no tienes instalado el paquete openxlsx, ejecuta antes: install.packages("openxlsx")

library(dplyr)
library(openxlsx)

# =============================================================================
# BLOQUE 1 — RUTAS (ajusta si tu carpeta no coincide)
# =============================================================================
# Lee directamente la salida de wilcoxon_comparison.R (no una copia manual en final_data/,
# que se quedaba vieja). Así el resumen siempre refleja el último análisis.
ruta_in  <- "C:/Users/andre/Desktop/TFM_AZTI/comparison/archivos/download_from_r/wilcoxon_denominador_CLASS.csv"
ruta_out <- "C:/Users/andre/Desktop/TFM_AZTI/comparison/archivos/download_from_r/Resumen_taxonomico_por_nivel.xlsx"

# =============================================================================
# BLOQUE 2 — CARGAR DATOS
# =============================================================================
# read.csv2 asume separador ";" y coma decimal, que es como está guardado el csv.
# Los "NA" sin comillas del csv se interpretan automáticamente como NA de R.
datos <- read.csv2(ruta_in, stringsAsFactors = FALSE, fileEncoding = "UTF-8")

# Niveles tal como aparecen en la columna "level", y el nombre que tendrá cada
# pestaña del Excel (en español, en el mismo orden)
niveles      <- c("Class", "Order", "Family", "Genus", "Species")
nombres_hoja <- c("Clase", "Orden", "Familia", "Genero", "Especie")

# =============================================================================
# BLOQUE 3 — TRADUCCIONES DE ETIQUETAS
# =============================================================================
traducir_grupo <- function(x) {
  case_when(
    x == "both"             ~ "Ambos métodos",
    x == "only_morphology"  ~ "Solo morfología",
    x == "only_eDNA"        ~ "Solo eDNA",
    TRUE ~ x
  )
}

# =============================================================================
# BLOQUE 4 — FUNCIÓN: construir la tabla resumen de un nivel
# =============================================================================
construir_resumen <- function(datos_nivel) {
  
  # Clasificación de dirección (misma lógica media+mediana que el detalle), para
  # contar cuántos SIGNIFICATIVOS son sobreestimados / subestimados / conflicto
  # en este nivel. Solo aplica al grupo "both".
  datos_nivel <- datos_nivel %>%
    mutate(
      # CORRECCION: se reutiliza la columna `direction` de wilcoxon_comparison.R en
      # lugar de recalcular la direccion aqui (ver nota en build_summary).
      clasif_dir = case_when(
        present_in != "both"                  ~ NA_character_,
        direction == "overestimated_in_eDNA"  ~ "over",
        direction == "underestimated_in_eDNA" ~ "under",
        direction == "conflict"               ~ "conflict",
        TRUE                                  ~ "nodiff"
      )
    )
  
  resumen <- datos_nivel %>%
    group_by(present_in) %>%
    summarise(
      n                               = n(),
      n_significativos_bonferroni     = sum(significant_bonferroni == "YES"),
      n_no_significativos_bonferroni  = sum(significant_bonferroni == "NO"),
      n_sobreestimados                = sum(clasif_dir == "over"     & significant_bonferroni == "YES", na.rm = TRUE),
      n_subestimados                  = sum(clasif_dir == "under"    & significant_bonferroni == "YES", na.rm = TRUE),
      n_conflicto                     = sum(clasif_dir == "conflict" & significant_bonferroni == "YES", na.rm = TRUE),
      n_conflicto_ns                  = sum(clasif_dir == "conflict" & significant_bonferroni == "NO",  na.rm = TRUE),
      .groups = "drop"
    ) %>%
    mutate(
      porcentaje                 = round(100 * n / sum(n), 1),
      grupo                      = traducir_grupo(present_in)
    ) %>%
    select(grupo, n, porcentaje, n_significativos_bonferroni,
           n_no_significativos_bonferroni,
           n_sobreestimados, n_subestimados, n_conflicto, n_conflicto_ns)
  
  # Forzar el orden fijo de los 3 grupos, rellenando con 0 si alguno no existiera
  orden_grupos <- c("Ambos métodos", "Solo morfología", "Solo eDNA")
  resumen <- resumen[match(orden_grupos, resumen$grupo), ]
  resumen$grupo <- orden_grupos
  resumen[is.na(resumen)] <- 0
  
  # Fila de total
  total <- data.frame(
    grupo                           = "TOTAL",
    n                                = sum(resumen$n),
    porcentaje                      = 100,
    n_significativos_bonferroni     = sum(resumen$n_significativos_bonferroni),
    n_no_significativos_bonferroni  = sum(resumen$n_no_significativos_bonferroni),
    n_sobreestimados                = sum(resumen$n_sobreestimados),
    n_subestimados                  = sum(resumen$n_subestimados),
    n_conflicto                     = sum(resumen$n_conflicto),
    n_conflicto_ns                  = sum(resumen$n_conflicto_ns)
  )
  resumen <- rbind(resumen, total)
  
  colnames(resumen) <- c("Grupo", "n", "% del total",
                         "n significativos (Bonferroni)",
                         "n no significativos (Bonferroni)",
                         "n sobreestimados en eDNA (sig.)",
                         "n subestimados en eDNA (sig.)",
                         "n conflicto media-mediana (sig.)")
  return(resumen)
}

# =============================================================================
# BLOQUE 5 — FUNCIÓN: construir la tabla detalle de un nivel
# =============================================================================
construir_detalle <- function(datos_nivel) {
  
  detalle <- datos_nivel %>%
    mutate(
      abundancia_referencia = case_when(
        present_in == "both"            ~ (mean_morpho + mean_cox1) / 2,
        present_in == "only_morphology" ~ mean_morpho,
        present_in == "only_eDNA"       ~ mean_cox1
      ),
      significativo_bonferroni = ifelse(significant_bonferroni == "YES", "Sí", "No"),
      # Dirección combinando MEDIANA y MEDIA (misma lógica que wilcoxon_comparison.R):
      #   - si mediana y media coinciden en dirección -> esa dirección (over/under)
      #   - si la mediana empata (p. ej. 0 en ambos métodos) la decide la media ->
      #     over/under. Varios sobre/subestimados tienen mediana = 0 (se comenta en el texto).
      #   - si la media empata, la decide la mediana
      #   - si media y mediana apuntan a direcciones OPUESTAS -> "Conflicto media-mediana"
      #     (los empates de mediana en 0 quedan fuera, van como over/under)
      dir_med_signo  = sign(median_cox1 - median_morpho),   #  1 over · -1 under · 0 empate
      dir_mean_signo = sign(mean_cox1   - mean_morpho),
      direccion = case_when(
        present_in != "both"                                  ~ NA_character_,
        dir_med_signo == dir_mean_signo & dir_med_signo ==  1 ~ "Sobreestimado en eDNA",
        dir_med_signo == dir_mean_signo & dir_med_signo == -1 ~ "Subestimado en eDNA",
        dir_med_signo == dir_mean_signo & dir_med_signo ==  0 ~ "No concordante",
        dir_med_signo  == 0 & dir_mean_signo ==  1            ~ "Sobreestimado en eDNA",
        dir_med_signo  == 0 & dir_mean_signo == -1            ~ "Subestimado en eDNA",
        dir_mean_signo == 0 & dir_med_signo  ==  1            ~ "Sobreestimado en eDNA",
        dir_mean_signo == 0 & dir_med_signo  == -1            ~ "Subestimado en eDNA",
        TRUE                                                  ~ "Conflicto media-mediana"
      ),
      grupo       = traducir_grupo(present_in),
      orden_grupo = case_when(                       # 1=Ambos, 2=Solo morfo, 3=Solo eDNA
        present_in == "both"            ~ 1,
        present_in == "only_morphology" ~ 2,
        present_in == "only_eDNA"       ~ 3
      ),
      orden_sig = ifelse(significant_bonferroni == "YES", 0, 1)   # significativos primero
    ) %>%
    arrange(orden_grupo, orden_sig, desc(abundancia_referencia)) %>%
    select(
      taxon, grupo, significativo_bonferroni, direccion,
      mediana_morfo = median_morpho, mediana_eDNA = median_cox1,
      media_morfo   = mean_morpho,   media_eDNA   = mean_cox1,
      p_valor = p_value, p_valor_bonferroni = p_adjust_bonferroni
    )
  
  colnames(detalle) <- c("Taxón", "Grupo", "Significativo (Bonferroni)",
                         "Dirección (solo 'Ambos métodos')",
                         "Mediana morfología", "Mediana eDNA",
                         "Media morfología", "Media eDNA",
                         "p-valor", "p-valor ajustado (Bonferroni)")
  return(detalle)
}

# =============================================================================
# BLOQUE 6bis — COBERTURA EN MIDORI (Orden / Familia / Género / Especie)
# =============================================================================
# Este bloque genera, para Orden, Familia, Género y Especie (no para Clase,
# porque nunca se comprobó la Clase contra MIDORI), una pestaña "<Nivel>_MIDORI"
# con dos tablas:
#   a) "Nivel más fino con referencia": SIEMPRE la misma tabla en las 4 pestañas,
#      porque describe la cobertura de las 78 especies de partida (no cambia
#      según el nivel de la pestaña en la que se muestra)
#   b) el listado de TODOS los taxones de ESE nivel en concreto (presentes y
#      ausentes en MIDORI a su propio nivel), con su ruta taxonómica completa
#
# IMPORTANTE — alcance: esta comprobación contra MIDORI solo se hizo para las
# 78 especies "Solo morfología" que se exportaron a midori_comparison_completo.py
# (fichero sp_morpho_compare.csv), NO para las 634/399/157/25 especies/géneros/
# familias/órdenes "Solo morfología" que aparecen en la tabla 2. Es decir: esta
# tabla de MIDORI es un subconjunto más pequeño y específico, coherente con el
# apartado de tu TFM que ya dice "78 especies". Los géneros/familias/órdenes de
# esta tabla salen de deduplicar esas 78 especies por su género/familia/orden.
#
# El fichero compare_MIDORI_con_order.csv lo genera midori_comparison.py: es un CSV
# normal (cabecera real en la 1ª línea, separador ";", codificación UTF-8), sin
# filas decorativas. Se lee directo, sin skip.

ruta_midori <- "C:/Users/andre/Desktop/TFM_AZTI/comparison/archivos/download_from_python/compare_MIDORI_con_order.csv"

midori <- read.csv2(ruta_midori, stringsAsFactors = FALSE, fileEncoding = "UTF-8")

a_logico <- function(x) toupper(trimws(as.character(x))) == "TRUE"
midori$en_MIDORI_especie <- a_logico(midori$en_MIDORI_especie)
midori$en_MIDORI_genero  <- a_logico(midori$en_MIDORI_genero)
midori$family_en_MIDORI  <- a_logico(midori$family_en_MIDORI)
midori$order_en_MIDORI   <- a_logico(midori$order_en_MIDORI)

# Una fila por taxón único a cada nivel (dedupe a partir de las 78 especies).
# Se conservan las 4 columnas booleanas (no solo la del propio nivel) porque
# hacen falta para la "cascada": si un taxón no tiene referencia a su propio
# nivel, se comprueba si la tiene a un nivel más alto (género > familia > orden).
midori_orden   <- midori[!is.na(midori$Order) & !duplicated(midori$Order),
                         c("Class", "Order", "order_en_MIDORI")]
midori_familia <- midori[!duplicated(midori$Family),
                         c("Class", "Order", "Family", "family_en_MIDORI", "order_en_MIDORI")]
midori_genero  <- midori[!duplicated(midori$Genus),
                         c("Class", "Order", "Family", "Genus",
                           "en_MIDORI_genero", "family_en_MIDORI", "order_en_MIDORI")]
midori_especie <- midori[!duplicated(midori$Specie),
                         c("Class", "Order", "Family", "Genus", "Specie",
                           "en_MIDORI_especie", "en_MIDORI_genero", "family_en_MIDORI", "order_en_MIDORI")]

# Qué tabla / columna de presencia / columnas de ruta usar en cada nivel
tablas_nivel_midori <- list(
  Order   = list(datos = midori_orden,   col_presencia = "order_en_MIDORI",
                 columnas_ruta = c("Class"),                       col_taxon = "Order"),
  Family  = list(datos = midori_familia, col_presencia = "family_en_MIDORI",
                 columnas_ruta = c("Class", "Order"),               col_taxon = "Family"),
  Genus   = list(datos = midori_genero,  col_presencia = "en_MIDORI_genero",
                 columnas_ruta = c("Class", "Order", "Family"),     col_taxon = "Genus"),
  Species = list(datos = midori_especie, col_presencia = "en_MIDORI_especie",
                 columnas_ruta = c("Class", "Order", "Family", "Genus"), col_taxon = "Specie")
)

# -----------------------------------------------------------------------------
# Función: tabla de "nivel más fino con referencia en MIDORI", calculada UNA
# VEZ sobre las 78 especies (no por nivel taxonómico). Para cada una de las 78
# especies "Solo morfología", comprueba si tiene referencia a nivel de especie;
# si no, si su género tiene referencia; si no, su familia; si no, su orden; y
# si nada de eso, "Ninguno". Es la misma tabla (36 especie / 31 género / 8
# familia / 2 orden / 1 ninguno) que va IGUAL en las 4 pestañas _MIDORI, porque
# describe la cobertura de las 78 especies de partida, no algo distinto por nivel.
# -----------------------------------------------------------------------------
construir_tabla_cascada_especies <- function(midori) {
  cascada  <- c("en_MIDORI_especie", "en_MIDORI_genero", "family_en_MIDORI", "order_en_MIDORI")
  etiquetas <- c(en_MIDORI_especie = "Especie", en_MIDORI_genero = "Género",
                 family_en_MIDORI = "Familia", order_en_MIDORI = "Orden")
  
  valores <- midori[, cascada, drop = FALSE]
  clasificacion <- apply(valores, 1, function(fila) {
    idx <- which(fila)[1]          # primera columna (de más fina a más gruesa) que sea TRUE
    if (is.na(idx)) "Ninguno" else etiquetas[[cascada[idx]]]
  })
  
  niveles_categoria <- c(unname(etiquetas[cascada]), "Ninguno")
  conteo <- table(factor(clasificacion, levels = niveles_categoria))
  
  resumen <- data.frame(
    `Nivel más fino con referencia` = names(conteo),
    `Nº especies` = as.integer(conteo),
    `% del total` = round(100 * as.integer(conteo) / sum(conteo), 1),
    check.names = FALSE
  )
  
  total <- data.frame(
    `Nivel más fino con referencia` = "Total", `Nº especies` = sum(resumen$`Nº especies`), `% del total` = 100,
    check.names = FALSE
  )
  rbind(resumen, total)
}

# -----------------------------------------------------------------------------
# Función: listado de TODOS los taxones (presentes y ausentes) en MIDORI,
# con su ruta taxonómica y una columna de estado. Se usa como parte de la
# tabla de "resumen" para que se vea taxón a taxón, no solo el recuento.
# Orden: primero los presentes, después los ausentes; dentro de cada bloque,
# alfabético por el nombre del taxón.
# -----------------------------------------------------------------------------
construir_lista_todos_midori <- function(tabla_nivel, columna_presencia, columnas_ruta, nombre_taxon_col) {
  tabla <- tabla_nivel[, c(columnas_ruta, nombre_taxon_col, columna_presencia)]
  
  tabla$Estado <- ifelse(tabla[[columna_presencia]], "Presente en MIDORI", "Ausente en MIDORI")
  tabla$orden_estado <- ifelse(tabla[[columna_presencia]], 0, 1)   # presentes primero
  tabla <- tabla[order(tabla$orden_estado, tabla[[nombre_taxon_col]]), ]
  
  # Columna con la ruta completa como texto, además de las columnas por separado
  tabla$Ruta_completa <- apply(tabla[, c(columnas_ruta, nombre_taxon_col)], 1,
                               function(x) paste(na.omit(x), collapse = " > "))
  
  tabla[[columna_presencia]] <- NULL
  tabla$orden_estado <- NULL
  
  traduccion_col <- c(Class = "Clase", Order = "Orden", Family = "Familia",
                      Genus = "Género", Specie = "Especie")
  colnames(tabla)[colnames(tabla) %in% names(traduccion_col)] <-
    traduccion_col[colnames(tabla)[colnames(tabla) %in% names(traduccion_col)]]
  colnames(tabla)[colnames(tabla) == "Ruta_completa"] <- "Ruta completa"
  
  rownames(tabla) <- NULL
  return(tabla)
}

# =============================================================================
# BLOQUE 6 — CONSTRUIR EL EXCEL, UNA PESTAÑA POR NIVEL
# =============================================================================
wb <- createWorkbook()

estilo_titulo <- createStyle(textDecoration = "bold", fontSize = 13)
estilo_header <- createStyle(textDecoration = "bold", fgFill = "#D9E1F2",
                             border = "Bottom", halign = "center")

# Estilos para la tabla de cascada: mismo azul clarito que el resto del Excel
# (estilo_header), no el teal de la foto de ejemplo. Fila Total en negrita con
# fondo claro, nota de fuente en cursiva.
estilo_header_cascada <- createStyle(textDecoration = "bold", fgFill = "#D9E1F2",
                                     border = "Bottom", halign = "center")
estilo_total_cascada <- createStyle(textDecoration = "bold", fgFill = "#DCE6F1",
                                    border = "Top", borderStyle = "thin")
estilo_fuente <- createStyle(textDecoration = "italic", fontColour = "#666666", fontSize = 9)

# Tabla de cascada: se calcula UNA sola vez (no depende del nivel) y se repite
# igual en las 4 pestañas _MIDORI
tabla_cascada_especies <- construir_tabla_cascada_especies(midori)

for (i in seq_along(niveles)) {
  
  nivel_actual <- niveles[i]
  hoja         <- nombres_hoja[i]
  
  datos_nivel <- datos %>% filter(level == nivel_actual)
  
  tabla_resumen <- construir_resumen(datos_nivel)
  tabla_detalle <- construir_detalle(datos_nivel)
  
  addWorksheet(wb, hoja)
  
  # --- Bloque resumen ---
  writeData(wb, hoja, paste0("Resumen — ", hoja), startRow = 1, startCol = 1)
  addStyle(wb, hoja, estilo_titulo, rows = 1, cols = 1)
  writeData(wb, hoja, tabla_resumen, startRow = 3, startCol = 1, headerStyle = estilo_header)
  
  # --- Bloque detalle (empieza unas filas después del resumen) ---
  fila_titulo_detalle <- 3 + nrow(tabla_resumen) + 3
  writeData(wb, hoja, paste0("Detalle de taxones — ", hoja), startRow = fila_titulo_detalle, startCol = 1)
  addStyle(wb, hoja, estilo_titulo, rows = fila_titulo_detalle, cols = 1)
  
  fila_header_detalle <- fila_titulo_detalle + 2
  writeData(wb, hoja, tabla_detalle, startRow = fila_header_detalle, startCol = 1, headerStyle = estilo_header)
  
  # Fila fija en la cabecera de la tabla de detalle. Como esta pestaña ya NO
  # lleva la tabla de MIDORI debajo (va en su propia pestaña, ver más abajo),
  # esta fila fija es válida para todo el scroll de la pestaña.
  freezePane(wb, hoja, firstActiveRow = fila_header_detalle + 1)
  setColWidths(wb, hoja, cols = 1:ncol(tabla_detalle), widths = "auto")
  
  cat("Pestaña generada:", hoja, "(", nrow(tabla_detalle), "taxones )\n")
  
  # --- Pestaña aparte para cobertura MIDORI (Orden, Familia, Género, Especie; no Clase) ---
  if (nivel_actual %in% names(tablas_nivel_midori)) {
    
    hoja_midori <- paste0(hoja, "_MIDORI")
    info <- tablas_nivel_midori[[nivel_actual]]
    tabla_todos_midori <- construir_lista_todos_midori(info$datos, info$col_presencia,
                                                       info$columnas_ruta, info$col_taxon)
    
    addWorksheet(wb, hoja_midori)
    
    # --- Tabla 1: "Nivel más fino con referencia" — IGUAL en las 4 pestañas MIDORI ---
    writeData(wb, hoja_midori, "Nivel más fino con referencia en MIDORI (78 especies 'Solo morfología' comprobadas)",
              startRow = 1, startCol = 1)
    addStyle(wb, hoja_midori, estilo_titulo, rows = 1, cols = 1)
    
    fila_cascada <- 2   # sin fila en blanco entre el título y la tabla
    writeData(wb, hoja_midori, tabla_cascada_especies, startRow = fila_cascada, startCol = 1, headerStyle = estilo_header_cascada)
    addStyle(wb, hoja_midori, estilo_total_cascada, rows = fila_cascada + nrow(tabla_cascada_especies), cols = 1:3)
    
    # (nota de fuente eliminada a petición)
    
    # --- Tabla 2: listado completo de taxones de ESTE nivel (presentes y ausentes), con ruta ---
    fila_titulo_todos <- fila_cascada + nrow(tabla_cascada_especies) + 3
    writeData(wb, hoja_midori, paste0("Taxones de ", hoja, " (presentes y ausentes en MIDORI)"),
              startRow = fila_titulo_todos, startCol = 1)
    addStyle(wb, hoja_midori, estilo_titulo, rows = fila_titulo_todos, cols = 1)
    
    fila_header_todos <- fila_titulo_todos + 1   # sin fila en blanco entre el título y la tabla
    writeData(wb, hoja_midori, tabla_todos_midori, startRow = fila_header_todos, startCol = 1, headerStyle = estilo_header)
    
    # Fila fija en la cabecera del listado de taxones (la tabla larga de esta pestaña)
    freezePane(wb, hoja_midori, firstActiveRow = fila_header_todos + 1)
    setColWidths(wb, hoja_midori, cols = 1:ncol(tabla_todos_midori), widths = "auto")
    
    cat("Pestaña generada:", hoja_midori, "(", nrow(tabla_todos_midori), "taxones en total )\n")
  }
}

saveWorkbook(wb, ruta_out, overwrite = TRUE)
cat("\nExcel guardado en:", ruta_out, "\n")
